from PIL import Image
im = Image.open('r135-dark-tooltip.png').convert('RGB')
# Panel fill is ~ (60,60,60) on plane (30,30,30). Find rows/cols where fill dominates, rows 60..110, x 10..140
def isfill(p): return abs(p[0]-60)<12 and abs(p[1]-60)<12 and abs(p[2]-60)<12
minx,maxx,miny,maxy = 9999,-1,9999,-1
for y in range(58,112):
    for x in range(10,140):
        if isfill(im.getpixel((x,y))):
            minx=min(minx,x); maxx=max(maxx,x); miny=min(miny,y); maxy=max(maxy,y)
print('panel bbox x%d..%d (w%d) y%d..%d (h%d)'%(minx,maxx,maxx-minx+1,miny,maxy,maxy-miny+1))
# corner radius: leftmost fill pixel per row at top
for y in range(miny, miny+7):
    for x in range(10,140):
        if isfill(im.getpixel((x,y))):
            print('row',y,'leftmost-fill',x); break
# interior fill samples + ink brightest
print('interior', im.getpixel((35,90)), im.getpixel((95,72)))
best=(0,None)
for y in range(miny+2,maxy-1):
    for x in range(minx+2,maxx-1):
        p=im.getpixel((x,y))
        if sum(p)>best[0]: best=(sum(p),(x,y,p))
print('brightest ink pixel', best)
print('centre x panel', (minx+maxx)/2, 'button centre 62; top', miny, 'vs button bottom 64')
